INSERT INTO `food_info` (`id`, `category_id`, `food_name`, `image`, `calories`, `protein`, `fat`, `carbohydrate`, `vitamin`, `mineral`, `cooking_method`, `description`, `status`, `deleted`, `create_time`, `update_time`) VALUES (1,11,'大米1','/uploads/food_rice.png',346.00,7.40,0.80,77.90,'维B1 0.11mg、维B2 0.05mg','钙 13mg、铁 2.3mg、锌 1.7mg','蒸煮为主，可做米饭、粥、炒饭','大米是最常见的主食，富含碳水化合物，是人体能量的主要来源',0,0,'2026-04-22 19:16:26','2026-09-13 21:28:18'),(2,11,'面粉','/uploads/food_flour.png',366.00,11.20,1.50,73.60,'维B1 0.28mg、维E 1.82mg','钙 31mg、铁 3.5mg、硒 7.8μg','可制作面条、馒头、饺子、面包等','小麦粉蛋白质含量较高，是北方地区的主要主食原料',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(3,12,'红薯','/uploads/food_sweet_potato.png',99.00,1.10,0.20,23.10,'维A 125μg、维C 26mg、维E 0.28mg','钙 23mg、钾 130mg、磷 39mg','蒸、烤、煮均可，也可做红薯粥','红薯富含膳食纤维和维生素A，有助于消化和视力保护',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(4,12,'土豆','/uploads/food_potato.png',76.00,2.00,0.20,16.50,'维C 27mg、维B6 0.30mg','钾 342mg、磷 40mg、镁 20mg','炒、炖、蒸、炸均可','土豆是世界第四大粮食作物，富含钾元素和维生素C',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(5,21,'菠菜','/uploads/food_spinach.png',24.00,2.60,0.30,3.60,'维A 487μg、维C 32mg、维K 483μg','铁 2.9mg、钙 73mg、镁 58mg','焯水后凉拌、炒食、做汤','菠菜铁含量丰富，含有大量叶酸，适合孕妇食用',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(6,21,'生菜','/uploads/food_lettuce.png',13.00,1.30,0.30,1.30,'维A 25μg、维C 13mg、维K 126μg','钙 18mg、钾 141mg、铁 0.9mg','生吃、做沙拉、包饭','生菜水分充足热量极低，是减脂饮食的理想选择',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(7,22,'胡萝卜','/uploads/food_carrot.png',32.00,1.00,0.20,7.70,'维A 688μg、维C 6mg、维K 13μg','钾 237mg、钙 27mg、磷 26mg','生吃、炒食、炖汤、榨汁','胡萝卜富含β-胡萝卜素，对眼睛和皮肤有益',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(8,23,'番茄','/uploads/food_tomato.png',15.00,0.90,0.20,2.50,'维C 14mg、维A 42μg、维K 8μg','钾 237mg、磷 24mg、镁 11mg','生吃、炒蛋、做汤、做酱','番茄含有丰富的番茄红素，具有抗氧化作用',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(9,23,'黄瓜','/uploads/food_cucumber.png',15.00,0.70,0.10,2.90,'维C 2.8mg、维K 16μg','钾 147mg、镁 13mg、磷 24mg','生吃、凉拌、炒食','黄瓜水分含量高达96%，是夏季消暑解渴的好食材',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(10,31,'草莓','/uploads/food_strawberry.png',32.00,0.70,0.30,5.70,'维C 59mg、叶酸 24μg','钾 153mg、磷 24mg、钙 16mg','直接食用、做果酱、搭配酸奶','草莓维C含量高于柑橘，口感酸甜，营养丰富',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(11,32,'橙子','/uploads/food_orange.png',47.00,0.90,0.10,8.50,'维C 53mg、叶酸 30μg、维A 11μg','钾 181mg、钙 40mg、磷 14mg','直接食用、榨汁','橙子是维C的优质来源，常吃有助于增强免疫力',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(12,41,'猪瘦肉','/uploads/food_lean_pork.png',143.00,20.30,6.20,1.50,'维B1 0.54mg、维B2 0.10mg','铁 3.0mg、锌 2.99mg、硒 9.5μg','炒、炖、蒸、红烧','猪瘦肉蛋白质含量高，是常见的优质蛋白来源',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(13,42,'牛腱肉','/uploads/food_beef_shank.png',106.00,20.10,2.00,1.20,'维B12 2.6μg、维B6 0.37mg','铁 2.8mg、锌 4.7mg、硒 10.6μg','卤、炖、涮火锅','牛肉低脂高蛋白，富含肌酸，适合健身人群',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(14,43,'鸡胸肉','/uploads/food_chicken_breast.png',133.00,31.00,3.60,0.00,'维B3 8.9mg、维B6 0.53mg','硒 27.6μg、磷 196mg、钾 256mg','煎、烤、水煮','鸡胸肉是高蛋白低脂肪的代表食材，健身减脂首选',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(15,51,'三文鱼','/uploads/food_salmon.png',208.00,20.40,13.40,0.00,'维D 11μg、维B12 3.2μg、维E 1.1mg','硒 36.5μg、磷 240mg、钾 363mg','刺身、煎、烤、蒸','三文鱼富含Omega-3脂肪酸，有益心血管健康',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(16,52,'虾仁','/uploads/food_shrimp.png',93.00,20.10,0.70,0.70,'维E 2.79mg、维B12 1.1μg','硒 33.7μg、钙 62mg、磷 228mg','白灼、炒、蒸、做饺子馅','虾仁高蛋白低脂肪，富含硒元素和优质蛋白',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(17,6,'鸡蛋','/uploads/food_egg.png',144.00,13.30,8.80,2.80,'维A 234μg、维D 2μg、维B2 0.32mg','铁 2.0mg、锌 1.1mg、硒 14.3μg','煮、煎、蒸、炒','鸡蛋被誉为完美蛋白质来源，氨基酸组成最接近人体需求',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(18,6,'牛奶','/uploads/food_milk.png',54.00,3.00,3.20,3.40,'维A 24μg、维D 0.6μg、维B2 0.14mg','钙 104mg、磷 73mg、钾 132mg','直接饮用、做酸奶、搭配麦片','牛奶是钙的最佳来源之一，每天一杯有助骨骼健康',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(19,7,'豆腐','/uploads/food_tofu.png',73.00,7.40,3.50,2.80,'维E 2.72mg、维K 2μg','钙 164mg、铁 1.9mg、镁 30mg','煎、炖、红烧、做汤','豆腐由大豆制成，富含植物蛋白和钙质，适合素食者',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(20,7,'黄豆','/uploads/food_soybean.png',390.00,35.10,16.00,25.30,'维E 18.9mg、维B1 0.41mg','钙 191mg、铁 8.2mg、锌 3.3mg','泡发后煮、做豆浆、做豆腐','黄豆蛋白质含量堪比肉类，是植物蛋白之王',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(21,8,'核桃','/uploads/food_walnut.png',654.00,15.20,65.20,13.70,'维E 43.2mg、维B6 0.54mg','镁 158mg、磷 346mg、锌 3.1mg','直接食用、碾碎拌菜、做糕点','核桃富含不饱和脂肪酸和维E，有益大脑健康',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(22,8,'杏仁','/uploads/food_almond.png',579.00,21.20,49.90,19.70,'维E 25.6mg、维B2 1.01mg','钙 269mg、镁 270mg、铁 3.7mg','直接食用、做杏仁露、烘焙','杏仁钙含量丰富，是坚果中的补钙好选择',0,0,'2026-04-22 19:16:26','2026-04-24 11:56:40'),(24,24,'西兰花','/uploads/food_broccoli.png',34.00,4.30,0.40,4.04,'维C 89mg、维K 101μg、叶酸 63μg','钙 47mg、铁 0.7mg、钾 316mg','焯水、清炒、蒸、做沙拉','西兰花被称为蔬菜皇冠，维C含量丰富，含有抗氧化物质萝卜硫素',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(25,21,'紫甘蓝','/uploads/food_purple_cabbage.png',28.00,1.40,0.10,5.27,'维C 57mg、维K 38μg、维A 56μg','钙 45mg、钾 243mg、铁 0.8mg','凉拌、做沙拉、清炒','紫甘蓝富含花青素，抗氧化能力强，颜色鲜艳适合做沙拉配菜',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(26,22,'山药','/uploads/food_yam.png',57.00,1.90,0.20,12.40,'维C 5mg、维B1 0.05mg','钾 213mg、磷 34mg、镁 14mg','蒸、煮粥、炖汤、清炒','山药是药食同源食材，含有黏液蛋白，有助于健脾养胃',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(27,13,'玉米','/uploads/food_corn.png',112.00,4.00,1.20,22.80,'维B1 0.16mg、维C 7mg、叶酸 46μg','钾 218mg、磷 89mg、镁 37mg','煮、蒸、烤、炒','玉米是粗粮代表，富含膳食纤维和叶黄素，对眼睛有保护作用',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(28,13,'燕麦','/uploads/food_oats.png',389.00,16.90,6.90,66.30,'维B1 0.76mg、维E 3.4mg','铁 4.7mg、锌 3.6mg、镁 177mg','煮粥、泡牛奶、做烘焙、做能量棒','燕麦是低GI粗粮，富含β-葡聚糖，有助于降低胆固醇和血糖',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(29,33,'苹果','/uploads/food_apple.png',52.00,0.30,0.20,11.40,'维C 4.6mg、维K 2.2μg','钾 107mg、磷 11mg、钙 6mg','直接食用、榨汁、做沙拉、烤苹果','苹果富含果胶和多酚类物质，每天一个苹果有助于维持健康',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(30,33,'香蕉','/uploads/food_banana.png',89.00,1.10,0.30,22.80,'维C 8.7mg、维B6 0.37mg','钾 358mg、镁 27mg、磷 22mg','直接食用、做奶昔、搭配燕麦、做面包','香蕉是运动前后的理想食物，富含钾元素，能快速补充能量',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(31,51,'鳕鱼','/uploads/food_cod.png',82.00,17.80,0.70,0.00,'维D 1μg、维B12 0.9μg、维E 0.6mg','硒 28μg、磷 203mg、钾 340mg','清蒸、煎、烤、炖','鳕鱼肉质细嫩，高蛋白低脂肪，DHA含量丰富，适合各年龄段食用',0,0,'2026-04-24 11:17:14','2026-04-24 11:17:14'),(33,55,'我不知道','',0.20,0.20,1.00,0.03,'','','','',0,0,'2026-09-13 20:59:19','2026-09-13 20:59:19');
