INSERT INTO `food_recipe` (`id`, `recipe_name`, `meal_type`, `total_calories`, `suitable_crowd`, `cooking_steps`, `image`, `description`, `status`, `deleted`, `create_time`, `update_time`) VALUES (1,'元气满满早餐碗','breakfast',420.00,'上班族、学生','1. 大米淘洗干净煮成白粥\n2. 鸡蛋煮至全熟，剥壳对半切开\n3. 牛奶倒入杯中微波加热1分钟\n4. 核桃仁取几颗放在粥上点缀\n5. 搭配一起食用','/uploads/recipe_breakfast_bowl.png','经典中式早餐组合，碳水蛋白质搭配均衡，简单快手适合工作日早晨',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(2,'全麦鸡蛋三明治','breakfast',380.00,'减脂人群、白领','1. 面粉制成的全麦吐司两片放入烤面包机\n2. 鸡蛋打散加盐煎成薄蛋饼\n3. 生菜洗净沥干铺在吐司上\n4. 放上蛋饼、番茄片，盖上另一片吐司\n5. 对角切开装盘，搭配牛奶','/uploads/recipe_egg_sandwich.png','西式轻食早餐，低脂高蛋白，膳食纤维丰富，饱腹感强',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(3,'红薯燕麦牛奶杯','breakfast',310.00,'养生人群、老年人','1. 红薯洗净切小块蒸熟\n2. 牛奶倒入碗中\n3. 放入蒸好的红薯块，轻轻压碎一部分\n4. 撒上杏仁碎\n5. 可根据喜好加少许蜂蜜','/uploads/recipe_sweet_potato_milk.png','软糯香甜的早餐选择，红薯富含膳食纤维促进消化，适合肠胃不好的人',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(4,'番茄鸡蛋盖浇饭','lunch',520.00,'大众人群','1. 大米淘洗后煮成米饭\n2. 番茄切十字花刀用开水烫去皮切块\n3. 鸡蛋打散炒至凝固盛出\n4. 锅中留底油炒番茄出汁，加少许糖和盐\n5. 倒入鸡蛋翻炒均匀\n6. 浇在米饭上即可','/uploads/recipe_tomato_egg_rice.png','家常味道的经典盖浇饭，番茄红素搭配优质蛋白，酸甜开胃又营养',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(5,'鸡胸肉蔬菜沙拉','lunch',350.00,'健身人群、减脂人群','1. 鸡胸肉用盐和黑胡椒腌制15分钟\n2. 平底锅少油煎至两面金黄切片\n3. 生菜撕成小块铺底\n4. 黄瓜切片、番茄切块摆放\n5. 胡萝卜切丝点缀\n6. 淋上橄榄油和柠檬汁拌匀','/uploads/recipe_chicken_salad.png','高蛋白低碳水的健身餐，蔬菜种类丰富维生素全面，饱腹不长胖',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(6,'菠菜豆腐汤配米饭','lunch',450.00,'素食者、老年人','1. 大米煮成白米饭\n2. 豆腐切成小方块\n3. 菠菜焯水切段\n4. 锅中加清水烧开放入豆腐煮3分钟\n5. 加入菠菜段、盐和香油调味\n6. 搭配米饭食用','/uploads/recipe_spinach_tofu_soup.png','清淡养胃的午餐搭配，植物蛋白和铁质丰富，适合不喜油腻的人群',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(7,'土豆炖牛肉套餐','lunch',580.00,'体力劳动者、青少年','1. 牛腱肉切块焯水去血沫\n2. 土豆去皮切滚刀块\n3. 胡萝卜切块备用\n4. 热锅加油炒香姜蒜，放入牛肉翻炒\n5. 加酱油、料酒和足量水炖40分钟\n6. 放入土豆和胡萝卜继续炖20分钟\n7. 调味收汁，搭配米饭','/uploads/recipe_beef_potato_stew.png','经典家常硬菜，牛肉补充蛋白和铁质，土豆饱腹感强，适合需要体力的人',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(8,'三文鱼蔬菜餐','dinner',400.00,'白领、注重心血管健康人群','1. 三文鱼用盐和柠檬汁腌制10分钟\n2. 平底锅少油煎至两面微焦\n3. 菠菜焯水后挤干水分摆盘\n4. 胡萝卜切丝用橄榄油快炒\n5. 三文鱼切块放在蔬菜上\n6. 淋上酱油和少许芥末','/uploads/recipe_salmon_veggie.png','富含Omega-3的健康晚餐，搭配绿色蔬菜维生素丰富，清淡不负担',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(9,'虾仁炒蛋配时蔬','dinner',380.00,'大众人群、孕妇','1. 虾仁洗净加料酒腌制\n2. 鸡蛋打散加少许盐\n3. 锅中油热先炒鸡蛋盛出\n4. 再炒虾仁至变色加入鸡蛋\n5. 另起锅炒菠菜作为配菜\n6. 搭配少量米饭食用','/uploads/recipe_shrimp_egg.png','两道小菜搭配的轻食晚餐，虾仁和鸡蛋都是优质蛋白，清爽不油腻',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(10,'清炒时蔬拼盘','dinner',280.00,'减脂人群、素食主义者','1. 菠菜焯水切段\n2. 黄瓜切片\n3. 胡萝卜切丝\n4. 豆腐切片煎至两面金黄\n5. 分别将蔬菜快炒调味\n6. 摆盘搭配在一起','/uploads/recipe_veggie_platter.png','低卡高纤维的晚餐选择，多种蔬菜搭配营养均衡，适合减脂期间食用',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(11,'水果酸奶杯','snack',180.00,'女性、儿童、办公室人群','1. 草莓洗净切半\n2. 橙子剥皮取果肉切块\n3. 牛奶（可换成酸奶效果更好）倒入杯中\n4. 放入水果块\n5. 撒上杏仁碎作为点缀','/uploads/recipe_fruit_yogurt.png','营养丰富的下午茶选择，维C含量高有助于增强免疫力，酸甜可口',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(12,'坚果能量小食','snack',250.00,'上班族、学生、健身人群','1. 核桃取仁掰成小块\n2. 杏仁取适量\n3. 黄豆提前炒熟\n4. 三种混合在一起装入小碗\n5. 每次取一小把作为加餐','/uploads/recipe_nut_snack.png','天然能量补给站，坚果和豆类富含优质脂肪和植物蛋白，少量即可补充能量',0,0,'2026-04-23 08:14:48','2026-04-24 11:56:40'),(14,'水果燕麦早餐碗','breakfast',380.00,'白领、学生、养生人群','1. 燕麦片倒入碗中，加入热牛奶浸泡5分钟\n2. 香蕉切片摆在燕麦上\n3. 苹果切小丁点缀\n4. 撒上少许杏仁碎\n5. 可淋上少许蜂蜜调味','/uploads/recipe_fruit_oatmeal.png','营养全面的快手早餐，燕麦提供持久饱腹感，水果补充维生素和天然甜味',0,0,'2026-04-24 11:20:49','2026-04-24 11:20:49'),(15,'山药小米养胃粥','breakfast',290.00,'肠胃不好人群、老年人、儿童','1. 大米和小米混合淘洗干净\n2. 山药去皮切小丁\n3. 锅中加水烧开放入米和山药\n4. 大火煮开转小火熬30分钟\n5. 出锅前加少许枸杞点缀','/uploads/recipe_yam_congee.png','健脾养胃的经典粥品，山药绵软香甜，搭配小米温和易消化',0,0,'2026-04-24 11:20:49','2026-04-24 11:20:49'),(16,'西兰花鸡胸肉便当','lunch',420.00,'健身人群、减脂人群、上班族','1. 鸡胸肉切块用生抽和黑胡椒腌制15分钟\n2. 西兰花掰成小朵焯水断生\n3. 锅中少油炒鸡胸肉至变色\n4. 加入西兰花翻炒，调入蚝油和盐\n5. 搭配少量米饭装入便当盒','/uploads/recipe_broccoli_chicken.png','高蛋白低脂肪的健身便当，西兰花和鸡胸肉搭配是经典的增肌减脂组合',0,0,'2026-04-24 11:20:49','2026-04-24 11:20:49'),(17,'玉米排骨汤套餐','lunch',550.00,'大众人群、儿童、老年人','1. 排骨焯水去血沫\n2. 玉米切段，胡萝卜切块\n3. 砂锅加水放入排骨大火烧开\n4. 转小火加入玉米和胡萝卜炖40分钟\n5. 加盐调味，搭配米饭食用','/uploads/recipe_corn_rib_soup.png','清甜滋补的家常汤品，玉米的甜味融入汤中，排骨补充蛋白质和钙质',0,0,'2026-04-24 11:20:49','2026-04-24 11:20:49'),(18,'清蒸鳕鱼配时蔬','dinner',350.00,'白领、孕妇、老年人','1. 鳕鱼解冻后用葱姜料酒腌制10分钟\n2. 盘底铺一层葱丝和姜片\n3. 鳕鱼放上，大火蒸8分钟\n4. 淋上蒸鱼豉油，撒葱丝\n5. 搭配焯水的西兰花和胡萝卜','/uploads/recipe_cod_steamed.png','清淡营养的晚餐选择，鳕鱼肉质嫩滑，富含DHA和优质蛋白',0,0,'2026-04-24 11:20:49','2026-04-24 11:20:49'),(19,'缤纷蔬果沙拉','dinner',260.00,'减脂人群、素食者、女性','1. 紫甘蓝切细丝\n2. 玉米粒煮熟沥水\n3. 黄瓜切片，番茄切块\n4. 所有食材混合放入大碗\n5. 淋上橄榄油和柠檬汁拌匀','/uploads/recipe_purple_salad.png','低卡高纤维的轻食晚餐，色彩缤纷食欲满满，紫甘蓝花青素抗氧化',0,0,'2026-04-24 11:20:49','2026-04-24 11:20:49'),(21,'12212','lunch',0.00,'','','','',0,1,'2026-09-15 11:38:02','2026-09-15 12:27:22');
