INSERT INTO `recommend_rule` (`id`, `rule_name`, `condition_json`, `priority`, `status`, `description`, `deleted`, `create_time`, `update_time`) VALUES (1,'久坐上班族低卡方案','{\"bmiRange\":\"18.5-24\",\"activityLevel\":[\"sedentary\",\"light\"],\"ageRange\":\"20-45\",\"caloriesRange\":\"1500-2000\",\"dietPreference\":\"清淡\"}',10,0,'适用于BMI正常、久坐或轻度活动的上班族，推荐热量在1500-2000kcal之间的清淡饮食方案',0,'2026-04-24 13:21:20','2026-04-24 13:21:20'),(2,'健身增肌高蛋白方案','{\"bmiRange\":\"18.5-28\",\"activityLevel\":[\"active\",\"very_active\"],\"ageRange\":\"18-40\",\"caloriesRange\":\"2200-3000\",\"gender\":1}',20,0,'适用于经常健身的男性用户，推荐高蛋白高热量饮食，帮助增肌塑形',0,'2026-04-24 13:23:51','2026-04-24 13:23:51'),(3,'女性轻食减脂方案','{\"bmiRange\":\"24-32\",\"activityLevel\":[\"sedentary\",\"light\"],\"ageRange\":\"20-45\",\"caloriesRange\":\"1200-1600\",\"gender\":2,\"dietPreference\":\"低脂\"}',15,0,'适用于BMI偏高的久坐女性，推荐低脂低卡饮食方案，帮助健康减脂',0,'2026-04-24 13:23:51','2026-04-24 13:23:51'),(4,'青少年成长营养方案','{\"ageRange\":\"12-18\",\"caloriesRange\":\"2000-2800\"}',25,0,'适用于12-18岁青少年，保证充足热量和均衡营养，支持身体发育',0,'2026-04-24 13:23:51','2026-04-24 13:23:51'),(5,'中老年养生方案','{\"activityLevel\":[\"sedentary\",\"light\"],\"ageRange\":\"50-80\",\"caloriesRange\":\"1400-1800\",\"dietPreference\":\"清淡\"}',18,0,'适用于中老年人群，推荐易消化、低盐清淡的饮食方案，注重钙质补充',0,'2026-04-24 13:23:51','2026-04-24 13:25:05'),(6,'素食主义者方案','{\"dietPreference\":\"素食\"}',10,0,'适用于素食偏好用户，推荐以豆制品、坚果、蔬菜为主的植物蛋白饮食方案',0,'2026-04-24 13:23:51','2026-04-24 13:23:51'),(7,'运动后恢复方案','{\"activityLevel\":[\"active\",\"very_active\"],\"caloriesRange\":\"1800-2500\"}',12,0,'适用于高强度运动后的用户，推荐富含碳水和蛋白质的恢复餐，帮助肌肉修复',0,'2026-04-24 13:23:51','2026-04-24 13:23:51');
